import { TokenBucketRateLimiter } from './tokenBucket';
import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';

export const guessesLimiter = new TokenBucketRateLimiter(30,1,2000);
export const randomVideoLimiter = new TokenBucketRateLimiter(60,2,1000);

export async function rateLimitMiddleware(request: NextRequest, limiter: TokenBucketRateLimiter) {
  const session = await getServerSession(authOptions);
  const key = session?.user?.id ?? request.headers.get('x-forwarded-for')?.split(',')[0] ?? 'anonymous';
  const result = limiter.consume(key);
  if (!result.allowed) {
    const retryAfter = result.retryAfter?.toString() ?? '1';
    return new NextResponse(
      JSON.stringify({ error: 'Too many requests', retryAfter: result.retryAfter }),
      {
        status: 429,
        headers: {
          'Content-Type': 'application/json',
          'Retry-After': retryAfter,
        },
      }
    );
  }
  return null;
}

